flowchart TD
  A["Start worker run"] --> B["Lock due outbox events"]
  B --> C{"Status still current?"}
  C -- "No" --> Z["Mark processed"]
  C -- "Yes" --> D{"Rule passes? (cut-off, late setting, correction window)"}
  D -- "No" --> Z
  D -- "Yes" --> E{"Guardians linked?"}
  E -- "No" --> F["Add to follow-up: No guardian contact"] --> Z
  E -- "Yes" --> G["For each guardian and channel: log, render, send"]
  G --> H{"Send OK?"}
  H -- "Yes" --> I["Log SENT"] --> Z
  H -- "No" --> J["Log FAILED and schedule retry"] --> Z

function processDueEvents(now):
    events = outbox.lockDue(now, limit = 200)        // FOR UPDATE SKIP LOCKED
    for event in events:
        record = attendance.get(event.attendanceId)
        if record.status != event.newStatus:
            outbox.markProcessed(event); continue

        settings = settings.forSchool(record.schoolId)
        type = rules.eventType(event, record, settings, now)   // ABSENCE | LATE | CORRECTION | null
        if type is null:
            outbox.markProcessed(event); continue

        guardians = guardians.forStudent(record.studentId)
        if guardians is empty:
            followUps.flag(record, "NO_GUARDIAN_CONTACT")
        for g in guardians:
            for channel in preferences.enabledChannels(g):
                if log.insertIfAbsent(record, g, type, channel):
                    message = templates.render(type, g.language, record)
                    result = adapters[channel].send(g, message)
                    log.update(result)
        outbox.markProcessed(event)
